const pendingReviewSignatures = `-- name: PendingReviewSignatures :many
SELECT o.id, o.source, o.bundle_id, o.window_title, o.binary_name, o.cwd,
       COUNT(t.ts) AS ticks, COALESCE(MAX(t.ts), 0) AS last_seen
FROM observations o
JOIN ticks t ON t.observation_id = o.id
WHERE t.project_id IS NULL
  AND o.id NOT IN (SELECT observation_id FROM ignored_observations)
GROUP BY o.id
ORDER BY ticks DESC
LIMIT ?
`

type PendingReviewSignaturesRow struct {
	ID          int64
	Source      string
	BundleID    string
	WindowTitle string
	BinaryName  string
	Cwd         string
	Ticks       int64
	LastSeen    interface{}
}

func (q *Queries) PendingReviewSignatures(ctx context.Context, limit int64) ([]PendingReviewSignaturesRow, error) {
	rows, err := q.db.QueryContext(ctx, pendingReviewSignatures, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PendingReviewSignaturesRow{}
	for rows.Next() {
		var i PendingReviewSignaturesRow
		if err := rows.Scan(
			&i.ID,
			&i.Source,
			&i.BundleID,
			&i.WindowTitle,
			&i.BinaryName,
			&i.Cwd,
			&i.Ticks,
			&i.LastSeen,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

