const upsertObservation = `-- name: UpsertObservation :one
INSERT INTO observations (source, bundle_id, window_title, binary_name, cwd, first_seen)
VALUES (?, ?, ?, ?, ?, ?)
ON CONFLICT (source, bundle_id, window_title, binary_name, cwd)
DO UPDATE SET id = id
RETURNING id
`

type UpsertObservationParams struct {
	Source      string
	BundleID    string
	WindowTitle string
	BinaryName  string
	Cwd         string
	FirstSeen   int64
}

func (q *Queries) UpsertObservation(ctx context.Context, arg UpsertObservationParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, upsertObservation,
		arg.Source,
		arg.BundleID,
		arg.WindowTitle,
		arg.BinaryName,
		arg.Cwd,
		arg.FirstSeen,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}
